<script setup>



import {computed, inject, ref, watch} from 'vue'
import WorkItemPicker from './WorkItemPicker.vue'
import {issueStatus, sourcePerson} from '../../shared/issuePresentation.js'


import {toast} from '../../shared/composables/toast.js'
const props=defineProps({show:Boolean,kind:String,me:Object,environments:Array,ids:{type:Array,default:()=>[]}})
const emit=defineEmits(['close','confirm'])
const api=inject('api'),q=ref(''),status=ref(''),person=ref(''),people=ref([]),rows=ref([]),selected=ref([]),page=ref(1),total=ref(0),busy=ref(false)
let sequence=0
const endpoint=computed(()=>props.kind==='version'?'release-versions':props.kind==='changes'?'changes':'work-items')
const labels={version:'发布版本',changes:'变更',work_items:'需求 / Bug'}
async function load(){const seq=++sequence;busy.value=true;try{const data=await api('api/'+endpoint.value+'/page?'+new URLSearchParams({page:String(page.value),page_size:'20',q:q.value,status:status.value,...(props.kind==='work_items'?{person:person.value,person_role:'related'}:{owner:person.value})}));if(seq!==sequence)return;rows.value=data.items||[];total.value=data.total||0}catch(e){toast(e.message,'error')}finally{if(seq===sequence)busy.value=false}}
function toggle(id,checked){if(props.kind==='version'){selected.value=[id];return}selected.value=checked?[...new Set([...selected.value,id])]:selected.value.filter(v=>v!==id)}
function search(){page.value=1;load()}
watch(()=>props.show,async v=>{if(!v){++sequence;return}if(props.kind==='work_items')return;selected.value=[...props.ids];q.value='';status.value='';person.value='';page.value=1;load();try{people.value=await api('api/'+endpoint.value+'/'+(props.kind==='work_items'?'people':'owners'))}catch{people.value=[]}})

import OptionPicker from '../../shared/components/OptionPicker.vue'



import {Button,Checkbox,Dialog,DialogContent,DialogDescription,DialogFooter,DialogHeader,DialogTitle,Empty,EmptyContent,EmptyDescription,EmptyHeader,Input,Pagination,PaginationContent,PaginationNext,PaginationPrevious,Spinner,Table,TableBody,TableCell,TableHead,TableHeader,TableRow} from '../../shared/shadcn-ui.js'

import {InputGroup,InputGroupInput,InputGroupAddon,InputGroupButton} from '../../shared/shadcn-ui.js'

import {XIcon} from '@lucide/vue'
</script>
<template><WorkItemPicker :show="show&&kind==='work_items'" purpose="delivery" :ids="ids" :me="me" :environments="environments" @close="emit('close')" @confirm="emit('confirm',$event.map(w=>w.id));emit('close')"/><Dialog :open="show&amp;&amp;kind!=='work_items'" @update:open="async v=>{if(!v){emit('close')}}"><DialogContent class="flex max-h-[92dvh] flex-col gap-0 overflow-hidden p-0 sm:max-w-[var(--editor-width)]" :class="false?'inset-0 h-dvh max-h-dvh w-screen max-w-none translate-x-0 translate-y-0 rounded-none sm:max-w-none':''" :style="{'--editor-width':typeof (&quot;min(1060px, 92vw)&quot;)==='number'?(&quot;min(1060px, 92vw)&quot;)+'px':(&quot;min(1060px, 92vw)&quot;)}" :show-close-button="true" @interact-outside="e=>{e.preventDefault()}"><DialogHeader class="shrink-0 border-b p-5 pr-12"><DialogTitle>{{'选择'+labels[kind]}}</DialogTitle><DialogDescription class="sr-only">详情与操作</DialogDescription></DialogHeader><div class="min-h-0 flex-1 overflow-auto p-5"><div class="filters"><InputGroup  class="min-w-0 "><InputGroupInput v-model="q" placeholder="搜索标题、编号或说明" @keyup.enter="search" v-bind="{&quot;aria-label&quot;:&quot;搜索交付来源&quot;}"/><InputGroupAddon align="inline-end"><InputGroupButton v-if="q" :disabled="false" size="icon-xs" aria-label="清空输入" @click="q='' "><XIcon/></InputGroupButton></InputGroupAddon></InputGroup><OptionPicker v-model="status" :options="kind==='version'?[{value:'ready',label:'已就绪'},{value:'completed',label:'已完成'}]:kind==='changes'?[{value:'ready',label:'已就绪'},{value:'draft',label:'待补齐'}]:[{value:'closed',label:'已关闭'},{value:'resolved',label:'已解决'},{value:'active',label:'处理中'}]" all-label="全部状态" :style="{width:'150px',maxWidth:'100%'}"/><OptionPicker v-model="person" :options="people"  all-label="全部人员" :style="{width:'180px',maxWidth:'100%'}"/><Button @click="search" variant="outline" size="default" type="button" :disabled="(busy)"><Spinner v-if="busy"/>搜索</Button></div><div class="table-scroll"><div class="console-table min-w-0 max-w-full"><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({x:840}).y?({x:840}).y+'px':undefined}"><Table class="table-fixed min-w-[var(--table-min-width)]" :style="{'--table-min-width':(({x:840}).x||({x:840}).minWidth||840)+'px'}"><TableHeader><TableRow><TableHead :style="{width:(180)+'px'}"><Checkbox v-if="kind!=='version'" aria-label="选择当前页" :model-value="rows.length>0&&rows.every(v=>selected.includes(v.id))" @update:model-value="rows.forEach(v=>toggle(v.id,$event===true))"/></TableHead><TableHead :style="{width:(200)+'px'}">编号</TableHead><TableHead :style="{width:(200)+'px'}">标题</TableHead><TableHead :style="{width:(120)+'px'}">状态</TableHead><TableHead :style="{width:(140)+'px'}">人员</TableHead></TableRow></TableHeader><TableBody><template v-for="(record,rowIndex) in (((rows)||[]).map((row,rowIndex)=>({...row,__rowKey:row.id}))||[])" :key="typeof (&quot;__rowKey&quot;)==='function'?(&quot;__rowKey&quot;)(record):record[&quot;__rowKey&quot;]??rowIndex"><TableRow><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record:row,rowIndex:rowIndex} in [{record,rowIndex}]"><div><Input :type="kind==='version'?'radio':'checkbox'" :model-value="selected.includes(row.id)" @change="value=>toggle(row.id,value===true)" v-bind="{&quot;name&quot;:&quot;delivery-source&quot;,&quot;aria-label&quot;:('选择 '+row.title)}"/></div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:row,rowIndex:rowIndex} in [{record,rowIndex}]"><div>{{row.external_id||row.version||'#'+row.id}}</div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:row,rowIndex:rowIndex} in [{record,rowIndex}]"><div>{{row.title}}</div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:row,rowIndex:rowIndex} in [{record,rowIndex}]"><div>{{issueStatus(row)}}</div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:row,rowIndex:rowIndex} in [{record,rowIndex}]"><div>{{sourcePerson(row.assigned_to||row.owner,row.person_labels)}}</div></template></div></TableCell></TableRow></template><TableRow v-if="!(((rows)||[]).map((row,rowIndex)=>({...row,__rowKey:row.id}))||[]).length"><TableCell :colspan="5"><Empty><EmptyHeader><EmptyDescription>{{busy?'正在加载…':'无匹配记录'}}</EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div></div></div><div class="table-footer"><span class="table-summary">已选 {{selected.length}} 项（跨页保留）</span><div class="flex flex-wrap items-center justify-end gap-3 py-4"><span class="mr-auto text-sm text-muted-foreground">共 {{total}} 项</span><Pagination class="mx-0 w-auto" :disabled="busy" :page="page" :total="total" :items-per-page="20" @update:page="(value=>{page=value;load()})($event)"><PaginationContent><PaginationPrevious /><span class="px-2 text-sm">{{page}} / {{Math.max(1,Math.ceil((total)/(20)))}}</span><PaginationNext /></PaginationContent></Pagination></div></div></div><DialogFooter class="shrink-0 flex-wrap border-t p-4"><Button @click="emit('close')" variant="outline" size="default" type="button">取消，保留原范围</Button><Button @click="emit('confirm',[...selected]);emit('close')" variant="default" size="default" type="button" :disabled="(busy||!selected.length)">确认选择</Button></DialogFooter></DialogContent></Dialog></template>
<style scoped>.filters,.pagination{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.filters{margin-bottom:16px}.table-scroll{overflow:auto}.pagination{margin-top:12px}.pagination>span:first-child{margin-right:auto}</style>
